CREATE TABLE IF NOT EXISTS pipe_batch_consumption_variances(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id),batch_id BIGINT NOT NULL,raw_material_id BIGINT NOT NULL,estimated_quantity NUMERIC(14,3) NOT NULL CHECK(estimated_quantity>0),actual_quantity NUMERIC(14,3) NOT NULL CHECK(actual_quantity>0),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(batch_id,raw_material_id),FOREIGN KEY(organization_id,batch_id) REFERENCES production_batches(organization_id,id),FOREIGN KEY(organization_id,raw_material_id) REFERENCES raw_materials(organization_id,id));
CREATE TABLE IF NOT EXISTS finished_goods_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,organization_id INTEGER NOT NULL REFERENCES organizations(id),goods_id BIGINT NOT NULL,quantity_delta NUMERIC(14,3) NOT NULL CHECK(quantity_delta<>0),movement_type TEXT NOT NULL CHECK(movement_type IN ('PRODUCTION','SALE','ADJUSTMENT')),reference TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,goods_id) REFERENCES finished_goods_catalog(organization_id,id));
CREATE INDEX IF NOT EXISTS ix_finished_goods_movements_org ON finished_goods_movements(organization_id,created_at DESC);